Bien sûr, voici un exemple de code pour un bot Discord avec une commande "bannir" à l'aide de Discord.js v14 :

1. Installez les dépendances requis en exécutant la commande suivante dans votre console de commande :

```
npm install discord.js dotenv
```

2. Créez un fichier `.env` et ajoutez les clés de votre bot Discord :

```
DISCORD_TOKEN=<votre-clé-de-bot>
DISCORD_PREFIX=<votre-préfixe-commande>
```

3. Créez un fichier `index.js` avec le code suivant :

```javascript
// Importez les dépendances
const { Client, GatewayIntentBits, Interaction, SlashCommandBuilder } = require('discord.js');
const { DISCORD_TOKEN, DISCORD_PREFIX } = require('./config');

// Créez un client Discord
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Définissez le préfixe de commande
client.commands = new Map();

// Ajoutez une commande de bannissement
client.commands.set('ban', {
  data: new SlashCommandBuilder()
    .setName('ban')
    .setDescription('Bannit un utilisateur du serveur')
    .addUserOption((option) =>
      option
        .setName('membre')
        .setDescription('Le membre à bannir')
        .setRequired(true)
    )
    .addStringOption((option) =>
      option
        .setName('raison')
        .setDescription('La raison du bannissement')
        .setRequired(false)
    ),
  execute: (interaction) => {
    const member = interaction.options.getUser('membre');
    const reason = interaction.options.getString('raison') || 'Pas de raison fournie';
    const guild = interaction.guild;

    // Vérifiez si l'utilisateur est un administrateur du serveur
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'Vous n'avez pas la permission de bannir les utilisateurs.',
        ephemeral: true,
      });
    }

    // Vérifiez si l'utilisateur à bannir est un membre du serveur
    if (!guild.members.cache.has(member.id)) {
      return interaction.reply({
        content: 'Cet utilisateur n'est pas un membre de ce serveur.',
        ephemeral: true,
      });
    }

    // Bannit l'utilisateur
    guild.members.ban(member, { reason });

    // Affichez un message de confirmation
    interaction.reply({
      content: `**${member.user.tag}** a été banni avec la raison: ${reason}`,
    });
  },
});

// Connexion du client Discord
client.on('ready', () => {
  console.log(`Bot en ligne comme ${client.user.tag}`);

  // Envoie des commandes disponibles
  client.application.commands.set(client.commands);
});

// Connexion de l'event de commande
client.on('interactionCreate', (interaction) => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (client.commands.has(commandName)) {
    client.commands.get(commandName).execute(interaction);
  }
});

// Connectez le client Discord
client.login(DISCORD_TOKEN);
```

