Voici une fonction C++ qui prend une référence à un `std::string` contenant du texte au format Markdown et renvoie un `std::string` contenant du texte au format HTML en utilisant la bibliothèque Pug de conversion de Markdown en HTML :

```cpp
#include <iostream>
#include <string>
#include <pugixml.hpp>

std::string convertMarkdownToHTML(const std::string& markdown) {
    // Créer un objet pugiXML et charger le texte Markdown
    pugi::xml_document doc;
    pugi::xml_parse_result result = doc.load_string(markdown.c_str());

    if (!result) {
        // Gérer les erreurs de parsing
        std::cerr << "Erreur de parsing de Markdown : " << result.description() << std::endl;
        return "";
    }

    // Charger le moteur de rendu Pug
    pugi::xml_node root = doc.document_element();
    pugi::xml_parse_options options;
    options.set(pugi::parse_declaration, false);
    options.set(pugi::parse_doctype, false);
    pugi::xerces_c::XMLPlatformUtils::Initialize();

    // Créer une nouvelle instance de Pug pour convertir le Markdown en HTML
    pugi::xhtml2html converter;
    converter.set_options(pugi::xhtml2html::html4);
    converter.parse_string(root.to_string());

    // Retourner le texte HTML converti
    std::string html = converter.final_result();
    pugi::xerces_c::XMLPlatformUtils::Terminate();
    return html;
}

int main() {
    std::string markdown = "Voici un **paragraphe en gras** et un *paragraphe en italique*.";
    std::string html = convertMarkdownToHTML(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

