```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string motSpecifique; // Mot à rechercher
    int compteur = 0; // Compteur d'occurrences du mot

    // Demander l'entrée du mot à rechercher
    cout << "Entrer le mot à rechercher: ";
    cin >> motSpecifique;

    // Ouvrir le fichier de texte pour lecture
    string nomFichier;
    cout << "Entrer le nom du fichier: ";
