    if (!lecture) {
        cerr << "Impossible d'ouvrir le fichier: " << nomFichier << endl;
        return 1;
    }

    // Lire le fichier ligne par ligne et compter les occurrences du mot
    string ligne;
    while (getline(lecture, ligne)) {
        // Convertir la chaîne de caractères en minuscules pour une recherche case-insensitive
        transform(ligne.begin(), ligne.end(), ligne.begin(), ::tolower);

        // Compter le nombre d'occurrences du mot dans la ligne actuelle
        size_t position = 0;
        while ((position = ligne.find(motSpecifique, position)) != string::npos) {
            compteur++;
            position += motSpecifique.length(); // Avancer de la longueur du mot pour la prochaine recherche
        }
    }

    // Fermer le fichier de texte
    lecture.close();

    // Afficher le nombre d'occurrences du mot
    cout << "Le mot \"" << motSpecifique << "\" apparaît " << compteur << " fois dans le fichier " << nomFichier << endl;

    return 0;
}
